-- Section order and show/hide for the CMS-edited pages, in already seeded documents (live and draft).
-- Home: adds the hero slider (three banners shipped in public/img/hero/), the "All products" section heading and a
-- "sections" list in which every section is shown, the products grid sits right after the statistics strip and the old
-- animated hero is hidden now that the slider exists. About and Contact: adds a "sections" list with every section shown.
-- Documents that already carry a "sections" list, or a slider or productsGrid block, keep what they have.
-- The banner images must also be in the media library to save the Home page: run `npm run seed -- --media-only` after
-- this migration (see cms/README.md).
CREATE FUNCTION pg_temp.with_sections(doc jsonb, additions jsonb) RETURNS jsonb LANGUAGE sql AS $$
  SELECT CASE WHEN jsonb_typeof(doc) = 'object' AND NOT doc ? 'sections'
    THEN doc || (SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb) FROM jsonb_each(additions) AS a(k, v) WHERE NOT doc ? k)
    ELSE doc END
$$;

